function makeFollowups(path, batch) {
  const { topic, idea } = path.at(-1);
  const root = path[0].topic;
  const project = followupProjects.find(({ id }) => id === idea?.project)
    ?? followupProjects.find(({ pattern }) => pattern.test(topic))
    ?? followupProjects.find(({ pattern }) => pattern.test(idea?.detail ?? "") || pattern.test(root));

  const toIdea = ([title, detail], index) => ({
    ...categories[index],
    label: nextStepLabels[index],
    title,
    detail,
    project: project?.id,
  });

  if (project?.id === "sound-map" && /早晚声音/.test(topic) && batch === 0) {
    return soundMapNextSteps.map(toIdea);
  }

  if (project && path.length === 2) {
    const start = batch * categories.length;
    const selected = project.ideas.slice(start, start + categories.length);
    if (selected.length === categories.length) return selected.map(toIdea);
  }

  const short = titleText(topic, 32);
  const subject = `「${titleText(root, 26)}」`;
  const source = `「${short}」`;
  const cue = matchedCues(topic) ?? matchedCues(root);
  const material = project?.material ?? (cue ? `能体现「${cue[0]}」的一张照片、一段录音或一条记录` : `与${subject}有关的一张照片、一条笔记或一个实物`);
  const trial = project?.trial ?? "请一位第一次看到的人说出他理解的重点和下一步";
  const time = [10, 15, 20, 30][batch % 4];
  const anchor = idea?.detail?.split(/[。！？]/u)[0]?.replace(/\s+/g, " ");
  const firstStep = anchor ? `沿用上一条的做法「${titleText(anchor, 46)}」。` : "";
  const sample = project?.subject ? `一张${project.subject}的前后对照表` : "一张前后对照表";

  const approaches = [
    [
      ["选一份素材做标记", `${firstStep}用 ${time} 分钟找${material}，写下来源，再圈出最能表现${source}的一处。`],
      ["把关键动作做成一分钟演示", `从${source}选一个动作，用纸或手机做出能演示的版本。计时走一遍，删掉一个不影响结果的步骤。`],
      ["写三张可照做的便签", `给${source}写三张便签，分别写清材料、动作和完成后会得到什么。拿着便签实际做一遍，补上漏写的东西。`],
      ["做两版，只比一个改动", `先做一个${source}的最小样本。复制一份，只改一个变量，把两次结果记在${sample}上。`],
      ["找一人试，记下第一处卡点", `把${source}的小样交给对方，${trial}。记下第一处停顿，只改这一处再试。`],
      ["留一张能复做的记录卡", `给${source}做一页记录，写下材料、用时和结果，放一张照片或截图。标出复做时需要保留的一个细节。`],
    ],
    [
      ["留一个改动前的样本", `${firstStep}准备${material}，拍照或截图留档。改动完成后，在相同条件下再留一份作对照。`],
      ["用一张纸画出交付物", `给${source}画一张 A4 草图，画出开头、关键细节和完成的样子。用 ${time} 分钟先做其中最小的一块。`],
      ["用手机计时试跑一遍", `把${source}拆成准备、操作、检查三步。计时做完，在最耗时的一步旁写下要提前准备的东西。`],
      ["试一份只用手边材料的版本", `列出做${source}最难准备的一样东西，用手边的材料替代一次。拍下结果，记下保留了什么效果。`],
      ["请两个人各读一次成品", `给两个人看${source}的小样，每人只问「你接下来会怎么做？」记下两个答案，选一处读错的地方重做。`],
      ["整理出下一次可直接用的材料", `把${source}的草稿、素材和试做记录放到一个文件夹，各写一句用途。给下次留一项 ${time} 分钟内能完成的任务。`],
    ],
  ];

  return approaches[batch % approaches.length].map(toIdea);
}
